usage.code:
// build once, when points or tension change
float[] table = SplineUtils.BuildLengthTable(points, tension, samplesPerSegment: 20);
float total = SplineUtils.TotalLength(table);

// per frame: advance by distance, not by t
travelled = Mathf.Repeat(travelled + speed * Time.deltaTime, total);
float t = SplineUtils.DistanceToT(table, travelled);
transform.position = SplineUtils.Evaluate(points, t, tension);
transform.rotation = Quaternion.LookRotation(SplineUtils.EvaluateTangent(points, t, tension));
